.gd{position:absolute;left:-2px;right:-2px;bottom:-8px;z-index:5;padding:1px 3px;border-radius:6px;text-align:center;white-space:normal;
 font:800 .46rem/1.2 var(--body);background:#0a1626f2;border:1px solid #8fc7ff;color:#d6ecff;box-shadow:0 0 10px #8fc7ff44;pointer-events:none}
.unit:has(>.gd) .name{visibility:hidden}
.unit:has(>.pv)>.gd{display:none}
@media (prefers-reduced-motion:no-preference){svg.pw-guards path{animation:pw-gd 1.2s linear infinite}}
@keyframes pw-gd{to{stroke-dashoffset:-14}}
.intent>.grow{top:auto!important;bottom:-10px}
.intent:has(>.grow){z-index:7!important}.intent>.grow{z-index:7}
.intent>.grow{background:#2a1606!important;opacity:1}
/* enrage growth sits inside its intent chip as a second line, so it never collides */
.intent:has(>.grow){display:inline-flex!important;flex-direction:column;align-items:center;gap:1px;line-height:1.15}
.intent>.grow{position:static!important;margin:0!important;padding:0 4px;font-size:.44rem;border-radius:99px}
