#app:has(>:is(.battle,.map,.screen))>.top{position:absolute!important;inset:0 0 auto 0;z-index:30;height:var(--pw-hud-h)!important;margin:0;padding:max(4px,env(safe-area-inset-top,0px)) max(12px,env(safe-area-inset-right,0px)) 0 max(12px,env(safe-area-inset-left,0px))!important;border:0!important;
 background:linear-gradient(180deg,#07060599 0%,#07060555 60%,transparent);pointer-events:none}
#app:has(>:is(.battle,.map,.screen))>.top>*{pointer-events:auto}
#app>:is(.battle,.map,.screen){margin:0!important;border:0!important;border-radius:0!important;box-shadow:none!important;width:100%;height:var(--pw-vh,100dvh)!important;min-height:var(--pw-vh,100dvh)!important;max-height:var(--pw-vh,100dvh);
 padding-top:calc(var(--pw-hud-h) + 2px)!important;padding-left:max(10px,env(safe-area-inset-left,0px))!important;padding-right:max(10px,env(safe-area-inset-right,0px))!important;padding-bottom:max(6px,env(safe-area-inset-bottom,0px))!important;overflow:clip}
#app>.screen:not(.heroes){overflow-y:auto}
#app>:is(.battle,.map,.screen)::after{inset:0!important;filter:brightness(.82) saturate(1.02)!important}
/* stage lighting: edge vignette + warm pool where the fight happens */
#app>:is(.battle,.map,.screen)::before{z-index:-1!important;background:
 radial-gradient(120% 90% at 50% 55%,transparent 45%,#050404b3 100%),
 radial-gradient(55% 35% at 50% 62%,#ffb8601a,transparent 70%),
 linear-gradient(180deg,#0806058c,transparent 22%,transparent 70%,#080605cc)!important}
/* HUD pieces */
#app>.top h1{font:700 1rem var(--display);letter-spacing:.14em;color:#f3d48a;text-shadow:0 0 14px #e8b95b55,0 2px 4px #000}
#app>.top .life{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 12px 0 10px;border-radius:999px;background:var(--pw-glass);border:1px solid #6fdc8c55;box-shadow:inset 0 1px 0 #ffffff12,0 4px 12px #0008;font:800 .8rem var(--body);color:#e9f7ec;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
#app>.top .life .lifebar{height:5px;border-radius:3px;box-shadow:inset 0 0 0 1px #0008}
#app>.top .gold{display:inline-flex;align-items:center;height:32px;padding:0 12px;border-radius:999px;background:var(--pw-glass);border:1px solid var(--pw-hair);color:#ffd98a;font:800 .8rem var(--body);box-shadow:inset 0 1px 0 #ffffff12,0 4px 12px #0008;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
#app>.top :is(.btn,button,a,details>summary){height:40px;min-width:40px;border-radius:999px!important;background:radial-gradient(120% 120% at 50% 0%,#3a332b,#16130f 70%)!important;border:1px solid #5a5146!important;
 box-shadow:inset 0 1px 0 #ffffff1f,inset 0 -2px 0 #0009,0 0 0 1px #000,0 4px 12px #000a!important;color:#efe6d2!important;font:700 .74rem var(--body);display:inline-flex;align-items:center;justify-content:center;padding:0 14px}
#app>.top :is(.btn,button,a,details>summary):hover{border-color:var(--pw-gold)!important}
#app>.top :is(.pw-infobtn,[data-act=new]){padding:0;width:40px}
#app>.top [data-act=new]{font-size:0!important}
#app>.top [data-act=new]::after{content:"⚑";font:700 1rem/1 var(--body);color:#e8e0cf}
/* glass + iron materials for every panel button */
:is(.screen,.battle,.map) .btn:not(.main):not(.unit),.screen .option:not(.hero-pick):not([data-rar]){background:linear-gradient(180deg,#2a2520e6,#16130fef 60%,#100e0bf2)!important;border:1px solid #5a5146!important;
 box-shadow:inset 0 1px 0 #ffffff1a,inset 0 -2px 0 #0008,0 0 0 1px #000a,0 8px 20px #000b!important;color:#efe6d2}
:is(.screen,.battle,.map) .btn:not(.main):not(.unit):not(:disabled):active,.screen .option:active{transform:translateY(1px);box-shadow:inset 0 1px 0 #ffffff10,inset 0 2px 6px #000a,0 0 0 1px #000a!important}
:is(.screen,.battle,.map) .btn:not(.main):not(.unit):not(:disabled):hover,.screen .option:not(:disabled):hover{border-color:var(--pw-gold)!important}
.screen .option{position:relative;border-radius:14px!important}
.screen .option::before{content:"";position:absolute;inset:3px;border-radius:11px;border:1px solid var(--pw-hair);pointer-events:none}
:is(.screen,.map) .btn.main,.screen .btn.main{background:linear-gradient(180deg,#ffe3a0,#e8b95b 45%,#b9862c)!important;color:#1a1408!important;border:1px solid #6b4d16!important;box-shadow:inset 0 1px 0 #fff6,inset 0 -2px 0 #0004,0 0 0 2px #120f0a,0 8px 18px #000c!important}
/* units: grounded with a contact shadow */
#app .battle .unit:not(.group)>.art,#app .battle .unit.group>.art{box-shadow:0 0 0 1px #000,0 10px 14px -4px #000e}
#app .battle .side::after{opacity:.75}
/* screen titles: engraved gold */
.screen h2{background:linear-gradient(180deg,#fff1cc,#e8b95b 55%,#a8782a);-webkit-background-clip:text;background-clip:text;color:transparent!important;filter:drop-shadow(0 2px 3px #000) drop-shadow(0 0 12px #e8b95b33)}
#app .battle .tally{top:calc(var(--pw-hud-h) - 2px)!important}
@media (max-aspect-ratio:3999/5000){#app>:is(.battle,.map){height:auto!important;max-height:none}}
@media (max-aspect-ratio:3999/5000){#app>.battle{padding-top:calc(var(--pw-hud-h) + 12px)!important}}
/* C1: readable text over bright paintings; tall screens never overflow upward */
#app>.screen:not(.heroes){align-content:safe center!important}
#app>.screen::before{background:
 radial-gradient(70% 60% at 50% 52%,#070605b3,#07060566 55%,transparent 80%),
 radial-gradient(120% 90% at 50% 55%,transparent 45%,#050404b3 100%),
 linear-gradient(180deg,#0806058c,transparent 22%,transparent 70%,#080605cc)!important}
#app>.screen>:is(p,.muted,.note,.summary),#app>.screen .lede{text-shadow:0 1px 2px #000,0 0 10px #000c;color:#ece4d2}
#app>.screen>.choices{justify-self:stretch;max-width:100%}
#app>.screen:not(.heroes){grid-template-columns:minmax(0,1fr)!important}
/* C1 r2 */
#app .battle .hand>.card .head{flex-direction:row-reverse;justify-content:flex-end;gap:4px}
#app .battle .hand>.card .cost{margin:0!important;flex:none}
#app .battle .tally[data-zero]{display:none}
@media (min-aspect-ratio:4/5){#app .battle .tally[data-zero]{display:none}#app .battle .tally{top:calc(var(--pw-hud-h) + 8px)!important}}
#app[data-pw-roomy] .battle{grid-template-rows:minmax(0,1fr) 26px 116px!important}
#app[data-pw-roomy] .battle .hand{height:116px}
#app[data-pw-roomy] .battle .hand>.card{zoom:1.2}
#app[data-pw-roomy] .battle .energy{zoom:1.15}
#app>.screen>p{background:radial-gradient(closest-side,#070605d9,#07060599 60%,transparent);padding:8px 28px;border-radius:999px}
/* keyword badges (Randall's codex mechanic icons) */
#app .battle .unit{position:relative}
.pw-kws{position:absolute;left:-7px;top:18px;display:grid;gap:3px;z-index:5;pointer-events:none}
.pw-kws i{display:grid;place-items:center;width:18px;height:18px;border-radius:50%;background:radial-gradient(circle at 40% 35%,#2a241c,#0e0c09) ;box-shadow:0 0 0 1px #c99c59,0 2px 5px #000c;font:800 .42rem/1 var(--body);font-style:normal;color:#f3dfb6;letter-spacing:0}
.pw-kws i[style],.pw-kws i[data-k]{background-image:var(--k,none),radial-gradient(circle at 40% 35%,#2a241c,#0e0c09);background-size:78%,cover;background-position:center;background-repeat:no-repeat}
#app[data-pw-roomy] .pw-kws i{width:20px;height:20px}
.pw-kws{top:12px;gap:1px;left:-6px}
.pw-kws i{width:15px;height:15px}
#app[data-pw-roomy] .pw-kws i{width:17px;height:17px}
/* ===== D1 hands-on battle: drag and drop, ability fan behind the loyalty diamond ===== */
.battle .hand>.card[data-act=play],.battle .side.you .unit.ally{touch-action:none;-webkit-user-select:none;user-select:none}
.pw-ghost{transform:rotate(-3deg) scale(1.06)!important;filter:drop-shadow(0 18px 22px #000d);opacity:.96;transition:box-shadow .12s}
.pw-ghost.pw-will-play{box-shadow:0 0 0 2px #8fdcff,0 0 26px 6px #5cc8ffaa!important}
.pw-lifted{opacity:.3!important}
#app .battle .unit.pw-drop>.art{box-shadow:0 0 0 2px #fff3c4,0 0 0 4px var(--pw-gold),0 0 26px 8px #e8b95bcc!important;transform:scale(1.06)}
#app .battle .side.foe .unit.pw-drop>.art{box-shadow:0 0 0 2px #ffd0c8,0 0 0 4px #e8705a,0 0 26px 8px #e8705acc!important}
.pw-dragging,.pw-dragging *{cursor:grabbing!important}
/* abilities folded behind the diamond */
#app .battle .controls :is([data-act=plus],[data-act=minus],[data-act=ult]){transition:opacity .16s ease,translate .16s ease}
#app .battle:not(.pw-abil-open) .controls :is([data-act=plus],[data-act=minus],[data-act=ult]){opacity:0;translate:-14px 0;pointer-events:none}
@media (max-aspect-ratio:3999/5000){#app .battle:not(.pw-abil-open) .controls :is([data-act=plus],[data-act=minus],[data-act=ult]){display:none}}
#app .battle .unit.hero .loyal{cursor:pointer;pointer-events:auto}
#app .battle .unit.hero .loyal::after{content:"";position:absolute;inset:-10px}
@keyframes pw-loyal-pulse{0%,100%{filter:drop-shadow(0 2px 3px #000) drop-shadow(0 0 0 #e8b95b00)}50%{filter:drop-shadow(0 2px 3px #000) drop-shadow(0 0 8px #ffd98a)}}
@media (prefers-reduced-motion:no-preference){#app .battle:not(.pw-abil-open):has(.controls [data-act=plus]:not(:disabled)) .unit.hero .loyal{animation:pw-loyal-pulse 1.8s ease-in-out infinite}}
#app .battle.pw-abil-open .unit.hero .loyal{background:linear-gradient(180deg,#fff6d8,#ffd98a 55%,#e8b95b)!important}
/* Formation button only shows while arranging (drag an ally onto your front ally instead) */
#app .battle .controls [data-act=arrange]:not(.chosen){display:none!important}
/* coach card */
.pw-coach{position:fixed;left:50%;top:50%;translate:-50% -50%;z-index:9998;width:min(340px,86vw);padding:16px 18px 12px;border-radius:16px;background:linear-gradient(180deg,#221d16f2,#110e0bf5);border:1px solid #6b5a33;box-shadow:inset 0 1px 0 #ffffff14,0 0 0 1px #000,0 24px 60px #000e;color:#efe6d2;font:500 .86rem/1.4 var(--body,system-ui)}
.pw-coach b{display:block;font:700 1rem var(--display,serif);color:#f3d48a;letter-spacing:.06em;margin-bottom:8px}
.pw-coach p{display:flex;gap:10px;align-items:flex-start;margin:6px 0}
.pw-coach i{font-style:normal;flex:none;width:24px;height:24px;display:grid;place-items:center;border-radius:50%;background:#2a241c;box-shadow:0 0 0 1px #c99c59;color:#ffd98a;font-size:.8rem}
.pw-coach span{display:block;text-align:right;margin-top:8px;font:700 .72rem var(--body,system-ui);letter-spacing:.1em;text-transform:uppercase;color:#a59a84}
/* ---------- D1 r2 (review): chip ghost, drop preview, Cancel swap, keyword rail + legend ---------- */
.pw-ghost{transform-origin:50% 100%;transition:transform .14s cubic-bezier(.2,.9,.3,1.2),box-shadow .12s}
.pw-ghost.pw-chip{transform:scale(.42)!important;filter:drop-shadow(0 8px 10px #000e)}
#app .battle .unit.pw-drop>.art{transform:scale(1.08)}
#app .battle .side.foe .unit.pw-drop>.art{box-shadow:0 0 0 2px #ffe0d8,0 0 0 5px #e8705a,0 0 34px 12px #e8705add!important;animation:pw-hover-pulse .6s ease-in-out infinite alternate}
@keyframes pw-hover-pulse{to{filter:brightness(1.18)}}
.pw-prev{position:absolute;left:50%;top:38%;translate:-50% -50%;z-index:8;pointer-events:none;padding:3px 10px;border-radius:999px;background:#120b08ee;box-shadow:0 0 0 1.5px #e8705a,0 4px 12px #000c;font:800 .8rem/1.1 var(--body);color:#ffd9cf;white-space:nowrap;animation:pw-prev-in .14s ease-out}
.pw-prev[data-dies]{background:#3a0d0aee;color:#fff;font-family:Cinzel,serif;letter-spacing:.06em;text-transform:uppercase;box-shadow:0 0 0 1.5px #ff8a70,0 0 16px #e8705a}
.pw-prev[data-dies]::before{content:'☠ '}
@keyframes pw-prev-in{from{scale:.6;opacity:0}}
/* targeting: Cancel takes End turn's place instead of overlapping it */
#app .battle .controls:has([data-act=cancel]) .btn.main{display:none!important}
@media (min-aspect-ratio:4/5){#app .battle .controls [data-act=cancel]{grid-row:3!important;align-self:end!important;min-height:46px!important;font-size:.74rem!important;margin:0!important}}
/* keyword rail: a row on the art's top-left, never spilling onto the neighbor */
.pw-kws{left:3px!important;top:3px!important;display:flex!important;gap:2px!important;max-width:calc(100% - 6px)}
.pw-kws i[hidden]{display:none}
.pw-kws .pw-more{font:800 .42rem/1 var(--body)}
.pw-kwdef{display:grid;gap:5px}
.pw-kwdef span{display:flex;gap:8px;align-items:center}
.pw-kwdef b{color:var(--pw-gold);font-family:Cinzel,serif}
.pw-kwdef i{flex:none;width:22px;height:22px;border-radius:50%;background:var(--k,none) center/78% no-repeat,radial-gradient(circle at 40% 35%,#2a241c,#0e0c09);box-shadow:0 0 0 1px #c99c59}
/* drop preview sits on the target's health, the chip rides higher so both stay visible */
.pw-prev{top:auto!important;bottom:6px;translate:-50% 0!important;font-size:.86rem!important;box-shadow:0 0 0 2px #e8705a,0 0 14px #e8705a99,0 4px 12px #000c!important}
/* targeting: the prompt toast stays above the raised card */
#app .battle .controls:has([data-act=cancel]){z-index:40;position:relative}
#app .battle .controls:has([data-act=cancel]) .log{position:relative!important;z-index:40;translate:0 -27px}
@media (max-aspect-ratio:3999/5000){#app .battle .controls:has([data-act=cancel]) .log{translate:none}}
/* narrow phones (320-440 wide, zoom 1): the floating HUD fits with Exit shown */
@media (max-width:440px){
 #app .top{gap:4px!important;padding-left:6px!important;padding-right:6px!important}
 #app .top>:is(.btn,a.btn),#app .top .deck>summary{min-width:34px!important;height:34px!important;min-height:34px!important;padding:0 8px!important}
 #app .top>.btn:not(.deck),#app .top>a.btn{width:34px!important;padding:0!important}
 #app .top>a.btn[href]{font-size:0!important}
 #app .top>a.btn[href]::before{content:'✕';font-size:.8rem}
 #app .top .deck>summary{font-size:.7rem!important}
 #app .top .life,#app .top .gold{font-size:.74rem!important;padding-left:8px!important;padding-right:8px!important}
}
@media (max-width:350px){
 #app .top{gap:3px!important}
 #app .top .life,#app .top .gold{font-size:.66rem!important;padding-left:6px!important;padding-right:6px!important}
 #app .top .deck>summary{font-size:.62rem!important;padding:0 6px!important}
 #app .top>:is(.btn,a.btn){width:32px!important;min-width:32px!important}
}
/* ---------- E1: Shandalar features (signature card, ante, dungeons). Hooks agreed with mechanics + sound. ---------- */
/* 1. Signature card: banner + slide out of the fallen enemy and flip into the row, last */
.screen .choices>.card[data-sig]{position:relative;overflow:visible;animation:pw-sig-in .9s cubic-bezier(.2,.9,.25,1.1) .45s both;box-shadow:0 0 0 1.5px #e8705a,0 0 22px 2px #e8705a66,0 10px 24px #000c}
.screen .choices>.card[data-sig]>.pw-sig{position:absolute;left:50%;top:-11px;translate:-50% 0;z-index:6;max-width:calc(100% + 18px);padding:3px 10px 4px;border-radius:4px;
 background:linear-gradient(#8d2a1f,#5a140f);box-shadow:0 0 0 1px #e8b95b,0 4px 10px #000c;font:700 .5rem/1.1 Cinzel,serif;letter-spacing:.06em;color:#ffe9c4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
 clip-path:polygon(0 0,100% 0,calc(100% - 5px) 50%,100% 100%,0 100%,5px 50%)}
@keyframes pw-sig-in{0%{opacity:0;transform:translateY(-46vh) scale(.55) rotateY(180deg);filter:brightness(2.2) saturate(.3)}
 45%{opacity:1;transform:translateY(-8px) scale(1.06) rotateY(90deg);filter:brightness(1.6)}
 75%{transform:translateY(-4px) scale(1.04) rotateY(0)}100%{transform:none;filter:none}}

/* 2. Ante: the wagered card rides on a gold plate above the elite */
.battle .side.foe{position:relative}
.battle .side.foe>.ante{position:absolute;left:50%;top:-6px;translate:-50% -100%;z-index:7;width:54px;pointer-events:none;display:grid;justify-items:center;animation:pw-ante-bob 3.2s ease-in-out infinite}
.battle .side.foe>.ante>.card{width:54px!important;min-height:0!important;height:72px;padding:2px!important;grid-template-rows:auto 34px!important;font-size:.36rem!important;overflow:hidden;transform:rotate(-4deg);box-shadow:0 0 0 1px #e8b95b,0 0 16px #e8b95b88,0 8px 14px #000c!important}
.battle .side.foe>.ante>.card>:nth-child(n+3),.battle .side.foe>.ante>.card .head b{display:none}
.battle .side.foe>.ante>.card .head{justify-content:flex-start;min-height:0}
.battle .side.foe>.ante::after{content:"Ante";margin-top:-6px;width:66px;height:16px;border-radius:50%;background:radial-gradient(ellipse at 50% 30%,#f6d58a,#b07a32 55%,#4a3014);position:relative;z-index:1;box-shadow:0 3px 8px #000c,inset 0 1px 0 #fff3;
 font:700 .42rem/16px Cinzel,serif;letter-spacing:.14em;text-transform:uppercase;text-align:center;color:#2a1a08}
@keyframes pw-ante-bob{50%{translate:-50% calc(-100% - 4px)}}
@media (max-aspect-ratio:3999/5000){#app .battle[data-ante] .side.foe{margin-top:78px}}
@media (min-aspect-ratio:4/5){.battle .side.foe>.ante{left:auto;right:calc(100% + 4px);top:50%;translate:0 -60%;animation:pw-ante-bob-w 3.2s ease-in-out infinite}}
@keyframes pw-ante-bob-w{50%{translate:0 calc(-60% - 4px)}}
/* the result after the fight: won = card back foiled + payout, lost = it shatters on the defeat screen */
.ante-result{position:relative;display:grid;grid-template-columns:auto auto;align-items:center;column-gap:12px;row-gap:2px;margin:2px auto 6px;width:max-content;max-width:100%;padding:5px 16px 5px 6px;border-radius:12px;background:#0b0907cc;box-shadow:0 0 0 1px #c99c5966}
.ante-result>.card{grid-row:1/3;width:46px!important;min-height:0!important;height:62px;padding:2px!important;grid-template-rows:auto 30px!important;font-size:.34rem!important;overflow:hidden;pointer-events:none}
.ante-result>.card>:nth-child(n+3),.ante-result>.card .head b{display:none}
.ante-result::after{grid-column:2;grid-row:1;align-self:end;font:700 .62rem/1.1 Cinzel,serif;letter-spacing:.1em;text-transform:uppercase}
.ante-result>.ante-pay{grid-column:2;grid-row:2;align-self:start;margin:0;font:600 .62rem/1.2 var(--body);color:#f2d496}
.ante-result:not(:has(.ante-pay))::after{grid-row:1/3;align-self:center}
.ante-result[data-r=won]::after{content:"Wager returned";color:var(--pw-gold)}
.ante-result[data-r=won]:has(>.card.foil)::after{content:"Wager returned · Foiled"}
.ante-result[data-r=won]>.card.foil{box-shadow:0 0 0 1px #fff3c4,0 0 14px #9fe3ff99,0 0 22px #e8b95b88!important}
.ante-result:is([data-r=lost],[data-r=burned])::after{content:"Your wager is lost";color:#ff9a80}
.ante-result[data-r=won]>.card{animation:pw-ante-won .9s cubic-bezier(.2,.9,.3,1.3) both}
.ante-result[data-r=won]::before{content:"";position:absolute;left:30px;top:50%;width:160px;height:160px;translate:-50% -50%;z-index:-1;border-radius:50%;pointer-events:none;
 background:repeating-conic-gradient(from 0deg,#e8b95b66 0 6deg,transparent 6deg 22deg);mask:radial-gradient(circle,#000 18%,transparent 68%);animation:pw-burst 1.6s ease-out both}
@keyframes pw-ante-won{from{transform:translateY(-60px) scale(.5);opacity:0;filter:brightness(2.4)}}
@keyframes pw-burst{from{scale:.2;opacity:0;rotate:-30deg}30%{opacity:1}to{scale:1.2;opacity:.35;rotate:20deg}}
.ante-result:is([data-r=lost],[data-r=burned])>.card:not(.pw-shard){animation:pw-ante-burn .62s ease-in .3s both}
@keyframes pw-ante-burn{0%{filter:none}25%{transform:translateX(-3px) rotate(-2deg)}50%{transform:translateX(3px) rotate(2deg)}99%{opacity:1;filter:sepia(1) saturate(3) brightness(1.35) hue-rotate(-20deg)}100%{opacity:0;filter:sepia(1) saturate(3) brightness(1.35) hue-rotate(-20deg)}}
.ante-result>.pw-shard{position:absolute;left:0;top:0;opacity:0;margin:0;pointer-events:none;filter:sepia(1) saturate(3) brightness(1.35) hue-rotate(-20deg);animation:pw-shard .9s cubic-bezier(.25,.6,.35,1) .92s forwards}
@keyframes pw-shard{0%{opacity:1;transform:none}100%{opacity:0;transform:translate(var(--dx),var(--dy)) rotate(var(--r))}}
/* elite's ante buff stays visible in battle */
.pw-ante-chip{position:absolute;left:50%;bottom:-4px;translate:-50% 100%;z-index:6;white-space:nowrap;padding:1px 7px;border-radius:99px;background:#3a0d0aee;box-shadow:0 0 0 1px #e8705a,0 0 0 2px #e8b95b55;font:700 .46rem/1.5 var(--body);color:#ffd2c6;pointer-events:none}
.pw-ante-chip::before{content:"Ante · ";color:#f2d496;font-family:Cinzel,serif}
/* the ante offer screen */
.screen.ante .ante-stake{display:grid;justify-items:center;margin:2px auto 4px;position:relative}
.screen.ante .ante-stake>.card{pointer-events:none;box-shadow:0 0 0 1.5px #e8b95b,0 0 26px #e8b95b66,0 12px 26px #000c!important;animation:pw-ante-bob2 3.2s ease-in-out infinite}
